<?php
session_start();
if(!isset($_SESSION['user_id']) && !isset($_SESSION['ngo_id'])) { header('Location: login.php'); exit; }
include 'db.php';
if(empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']!=='POST' || !hash_equals($_SESSION['csrf_token'],$_POST['csrf_token']??'')) { header('Location: delivery_track.php'); exit; }
$userId=(int)($_SESSION['user_id']??0); $ngoId=(int)($_SESSION['ngo_id']??0); $returnPage=$ngoId>0?'ngo_accepted_donations.php':'delivery_track.php'; $jobId=(int)($_POST['delivery_id']??0); $action=$_POST['action']??'';
if($jobId<=0 || !in_array($action,['accept','reject'],true)) { header('Location: '.$returnPage); exit; }
mysqli_begin_transaction($conn);
try { $where=$ngoId>0?"r.ngo_id=$ngoId":"d.receiver_id=$userId"; $q=mysqli_query($conn,"SELECT d.assigned_delivery_man_id,d.proposed_charge,d.request_id FROM deliveries d LEFT JOIN requests r ON d.source_table='requests' AND r.request_id=d.request_id WHERE d.delivery_id=$jobId AND $where FOR UPDATE"); $job=$q?mysqli_fetch_assoc($q):null; if(!$job || $job['proposed_charge']===null) throw new Exception('Delivery charge is not available.'); if($action==='accept') { $charge=(float)$job['proposed_charge']; if(!mysqli_query($conn,"UPDATE deliveries SET accepted_charge=$charge, charge_status='Accepted', status='Charge Accepted', charge_accepted_at=NOW(), updated_at=NOW() WHERE delivery_id=$jobId")) throw new Exception(mysqli_error($conn)); $requestId=(int)$job['request_id']; $manId=(int)$job['assigned_delivery_man_id']; $pickup=mysqli_query($conn,"SELECT pickup_id FROM pickups WHERE request_id=$requestId LIMIT 1"); if($pickup && mysqli_num_rows($pickup)>0) { mysqli_query($conn,"UPDATE pickups SET delivery_id=$manId, status='Charge Accepted' WHERE request_id=$requestId"); } else { if(!mysqli_query($conn,"INSERT INTO pickups (request_id,date,time,status,delivery_id) VALUES ($requestId,CURDATE(),CURTIME(),'Charge Accepted',$manId)")) throw new Exception(mysqli_error($conn)); } } else { $manId=(int)$job['assigned_delivery_man_id']; if(!mysqli_query($conn,"UPDATE deliveries SET assigned_delivery_man_id=NULL, proposed_charge=NULL, accepted_charge=NULL, charge_status='Rejected', status='Open', charge_rejected_at=NOW(), updated_at=NOW() WHERE delivery_id=$jobId")) throw new Exception(mysqli_error($conn)); if($manId>0) mysqli_query($conn,"UPDATE delivery_man SET availability='Available' WHERE delivery_id=$manId"); } mysqli_commit($conn); header('Location: '.$returnPage.'?message=charge_'.$action.'ed'); exit; } catch(Exception $e) { mysqli_rollback($conn); header('Location: '.$returnPage.'?error='.urlencode($e->getMessage())); exit; }
